/* DINGJIANG ONE — enterprise workspace, local operating books. */
const NAV_GROUPS=[
 ['decision','经营决策',[['overview','经营总览','grid'],['flow','业务工作台','layers'],['approvals','审批中心','check']]],
 ['sales','营销与渠道',[['orders','销售订单','orders'],['customers','客户与经销商','users'],['channels','渠道经营','building'],['ads','广告与归因','target']]],
 ['operations','产供销协同',[['procurement','采购管理','briefcase'],['inventory','库存计划','supply'],['warehouses','仓储流水','truck'],['production','生产工单','factory'],['products','产品与 BOM','layers'],['quality','质量验收','quality']]],
 ['finance','财务管理',[['finance','结算对账','finance'],['journals','会计凭证','receipt'],['profit','产品损益','trend'],['receivables','应收管理','clock']]],
 ['governance','数据与合规',[['data','数据质量','database'],['lineage','指标血缘','link'],['dictionary','指标字典','list'],['controls','内控与证据','shield'],['audit','操作审计','search'],['access','角色与权限','lock']]],
 ['technology','IT 管理',[['infrastructure','全球基础设施','globe'],['integrations','系统集成','link'],['projects','项目与预算','roadmap'],['assets','IT 资产','building'],['suppliers','供应商管理','users'],['strategy','建设蓝图','layers']]]
];
const THEMES=[{id:'indigo',name:'靛蓝 · 专业',description:'经营驾驶舱',image:'assets/ui-indigo.png'},{id:'graphite',name:'石墨 · 精密',description:'业务工作台',image:'assets/ui-graphite.png'},{id:'midnight',name:'深海 · 指挥',description:'财务驾驶舱',image:'assets/ui-midnight.png'}];
nav.splice(0,nav.length,...NAV_GROUPS.flatMap(g=>g[2]),['settings','工作空间设置','settings'],['research','调研与建设依据','search']);
let collapsedGroups=new Set(['governance','technology']);
let selectedOrder=state.orders.find(o=>o.status==='待发货')?.id||state.orders[0]?.id;
let flowPage=1,approvalType='all',dashboardFilter='all';
let chartInstances=[];
let inventoryCheckpoint=Object.fromEntries(state.products.map(p=>[p.sku,p.stock]));
function resetCheckpoint(){inventoryCheckpoint=Object.fromEntries(state.products.map(p=>[p.sku,p.stock]));selectedOrder=state.orders.find(o=>o.status==='待发货')?.id||state.orders[0]?.id;flowPage=1;filter='all';statusFilter='all';orderQuery='';}
function log(action,object,detail){
 for(const p of state.products){const delta=p.stock-(inventoryCheckpoint[p.sku]??p.stock);if(delta){const source=state.purchaseOrders.find(x=>x.id===object)||state.workOrders.find(x=>x.id===object);state.stockMovements??=[];state.stockMovements.unshift({id:'MOV-'+String(state.stockMovements.length+1).padStart(5,'0'),sku:p.sku,source:object,sourceOrder:object.startsWith('SO-')?object:source?.sourceOrder||'',type:delta<0?'销售出库':object.startsWith('MO-')?'生产入库':'采购入库',qty:delta,date:state.asOf||'2026-09-27'});inventoryCheckpoint[p.sku]=p.stock;}}
 state.audit.unshift({id:'LOG-'+String(state.audit.length+1).padStart(5,'0'),time:new Date().toLocaleString('zh-CN',{hour12:false}),actor:role,action,object,detail});persist();
}
function footer(){return `<footer class="pagefoot"><span>鼎匠 ONE · 集团数字化工作空间</span><span>${storageAvailable?'自动保存已开启':'当前会话'} · <button data-action="about">数据口径与版本</button></span></footer>`;}
function shell(){const group=NAV_GROUPS.find(g=>g[2].some(n=>n[0]===route));if(group)collapsedGroups.delete(group[0]);document.querySelector('#app').innerHTML=`<div class="shell"><div class="mobile-overlay" data-action="menu"></div><aside class="sidebar"><a class="brand" href="#overview" aria-label="鼎匠 ONE 首页"><img src="assets/logo.png" alt="鼎匠 ONE 标识"><div><strong>鼎匠 <span>ONE</span></strong><small>DINGJIANG ONE</small></div></a><nav class="sidebar-nav" aria-label="业务模块">${NAV_GROUPS.map(g=>`<section class="nav-group ${collapsedGroups.has(g[0])?'collapsed':''}" data-group-container="${g[0]}"><button class="nav-group-title" data-group="${g[0]}" aria-expanded="${!collapsedGroups.has(g[0])}"><span>${g[1]}</span><span class="chevron">${icon('chevron')}</span></button><div class="nav-children">${g[2].map(n=>`<button class="navitem ${route===n[0]?'active':''}" data-route="${n[0]}" ${route===n[0]?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span>${n[0]==='approvals'?`<span class="nav-count">${approvalQueue().length}</span>`:''}${n[0]==='finance'?`<span class="nav-count">${state.orders.filter(o=>o.status==='待结算').length}</span>`:''}</button>`).join('')}</div></section>`).join('')}</nav><div class="sidebar-bottom"><button data-route="settings">${icon('settings')} 工作空间设置</button><span class="side-version">ONE 2.0</span></div></aside><main class="main"><header class="topbar"><div class="workspace-switch"><button class="menu-toggle" data-action="menu" aria-label="打开导航">${icon('menu')}</button>${icon('building')}<span>集团工作空间</span><span class="workspace-detail"><small> / ${group?.[1]||'偏好设置'}</small></span></div><div class="top-actions"><label class="top-select">${icon('layers')}<select id="scenario-select" aria-label="业务数据方案">${SCENARIOS.map(s=>`<option value="${s.id}" ${s.id===activeScenario?'selected':''}>${s.name}</option>`).join('')}</select></label><label class="top-select">${icon('grid')}<select id="theme-select" aria-label="界面风格">${THEMES.map(t=>`<option value="${t.id}" ${t.id===uiTheme?'selected':''}>${t.name}</option>`).join('')}</select></label><span class="top-divider"></span><button class="search-trigger" data-action="search" aria-label="全局搜索">${icon('search')}<span class="search-words">搜索</span><kbd>⌘ K</kbd></button><button class="notification-button" data-action="notifications" aria-label="待办通知">${icon('bell')}<span class="notification-dot"></span></button><div class="role-wrap"><span class="avatar">${role==='IT 总监'?'IT':role.slice(0,1)}</span><select id="role" class="role-select" aria-label="操作角色">${['IT 总监','财务经理','供应链经理','审计观察员'].map(r=>`<option ${r===role?'selected':''}>${r}</option>`).join('')}</select></div></div></header><div class="content" id="content"></div></main></div>`;}
function businessMetrics(){const orders=state.orders.filter(o=>dashboardFilter==='all'||o.biz===dashboardFilter);const value=orders.reduce((s,o)=>s+amount(o),0);return{orders,value,profit:orders.reduce((s,o)=>s+profit(o),0),margin:value?orders.reduce((s,o)=>s+profit(o),0)/value*100:0,stock:state.products.reduce((s,p)=>s+p.stock,0),pending:state.orders.filter(o=>o.status==='待结算'),coverage:state.products.reduce((s,p)=>s+p.stock,0)/state.products.reduce((s,p)=>s+p.daily,0)}}
function executiveKpis(finance=false){const m=businessMetrics();return kpis(finance?[
 ['已入账收入',money(state.orders.filter(o=>o.status==='已入账').reduce((s,o)=>s+amount(o),0)),'',`${state.journals.length} 张会计凭证`,'finance'],['待结算净额',money(m.pending.reduce((s,o)=>s+net(o),0)),'',`${m.pending.length} 笔订单待核对`,'clock'],['贡献利润率',m.margin.toFixed(1),'%','扣除标准成本与渠道履约费用','trend'],['本期控制留证',state.controls.filter(c=>c.status==='已留证').length+'/'+state.controls.length,'项','复核记录与来源单据关联','shield']
 ]:[['本月订单金额',money(m.value),'',`${m.orders.length} 笔订单 · CNY / 不含税`,'finance'],['订单贡献利润率',m.margin.toFixed(1),'%','收入 − 成本 − 渠道履约费用','trend'],['库存覆盖天数',m.coverage.toFixed(1),'天',`${m.stock.toLocaleString()} 台可用库存`,'supply'],['待处理业务事项',approvalQueue().length,'项',`${m.pending.length} 笔结算待核对`,'check']]);}
function approvalQueue(){return [...state.orders.filter(o=>o.status==='待审核').map(o=>({id:o.id,type:'订单',title:product(o.sku).name+' · '+o.qty+' 台',amount:amount(o),owner:o.owner||'渠道运营',action:'order-next',status:'待审核'})),...state.purchaseOrders.filter(p=>p.status==='待审核').map(p=>({id:p.id,type:'采购',title:product(p.sku).name+' · '+p.qty+' 台',amount:p.qty*product(p.sku).cost,owner:'采购管理',action:'po-next',status:'待审核'})),...state.workOrders.filter(w=>w.status==='待质检').map(w=>({id:w.id,type:'质检',title:product(w.sku).name+' · '+w.qty+' 台',amount:w.qty*product(w.sku).cost,owner:'质量管理',action:'mo-next',status:'待质检'}))];}
function pipeline(){const stages=[['客户订单',state.orders.length,'orders','orders','全部业务订单'],['采购补货',state.purchaseOrders.filter(p=>p.status!=='已收货').length,'briefcase','procurement','进行中的采购'],['生产制造',state.workOrders.filter(w=>w.status!=='已完工').length,'factory','production','进行中的工单'],['交付出库',state.orders.filter(o=>o.status==='待发货').length,'truck','warehouses','待履约订单'],['结算对账',state.orders.filter(o=>o.status==='待结算').length,'finance','finance','待核对结算'],['凭证入账',state.journals.length,'receipt','journals','已生成凭证']];return `<section class="panel pipeline-panel"><div class="panel-head"><h2>产供销 · 业财全链路</h2><button class="text-btn" data-route="flow">业务工作台 ${icon('arrow')}</button></div><div class="pipeline">${stages.map((s,i)=>`${i?`<span class="pipeline-separator">${icon('arrow')}</span>`:''}<button class="pipeline-stage" data-route="${s[3]}"><span class="stage-symbol">${icon(s[2])}</span><span><span class="label">${s[0]}</span><strong>${s[1]} <small>笔</small></strong><small>${s[4]}</small></span></button>`).join('')}</div></section>`;}
function channelSummary(){const map={};for(const o of businessMetrics().orders)map[o.channel]=(map[o.channel]||0)+amount(o);const total=Object.values(map).reduce((s,n)=>s+n,0);return Object.entries(map).sort((a,b)=>b[1]-a[1]).slice(0,4).map(([name,value])=>`<div class="channel-mini"><span>${esc(name)}</span><div class="bar"><span style="width:${total?value/total*100:0}%"></span></div><span class="share">${total?(value/total*100).toFixed(1):0}%</span></div>`).join('');}
function compactOrders(orders,mode='overview'){return `<div class="table-wrap"><table><thead><tr><th>订单编号 / 客户</th><th>渠道 / 业务</th><th>产品 / 数量</th><th class="amount-cell">订单金额</th><th>状态</th><th>操作</th></tr></thead><tbody>${orders.map(o=>`<tr class="${mode==='flow'&&o.id===selectedOrder?'selected':''}"><td><button class="text-btn mono" data-action="${mode==='flow'?'select-order':'open-flow'}" data-id="${o.id}">${o.id}</button><small>${esc(o.customer)}</small></td><td>${esc(o.channel)}<small>${o.biz==='b2b'?'TOB 分销':'TOC 零售'}</small></td><td>${o.sku}<small>${o.qty} 台 · ${esc(product(o.sku).warehouse)}</small></td><td class="amount-cell">${money(amount(o))}</td><td>${statusBadge(o.status)}</td><td>${btn(mode==='flow'?'查看链路':'处理','select-order','small',`data-id="${o.id}"`)}</td></tr>`).join('')}</tbody></table>${orders.length?'':'<div class="empty">没有符合条件的订单。</div>'}</div>`;}
function executiveOverview(){if(uiTheme==='graphite')return flowWorkbench();const financial=uiTheme==='midnight';const m=businessMetrics();return head(financial?'财务经营驾驶舱':'经营总览',financial?'FINANCIAL COMMAND CENTER':'EXECUTIVE OVERVIEW','从业务事实到经营决策，让每一笔增长清晰可见。',btn(icon('download')+'导出报表','export')+btn(icon('layers')+'业务工作台','open-workbench','primary'))+`<div class="filterbar"><div class="segmented">${[['all','全部业务'],['b2c','TOC 零售'],['b2b','TOB 分销']].map(x=>`<button data-dashboard-filter="${x[0]}" class="${dashboardFilter===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><span class="subtext" style="margin-left:auto">${icon('calendar')} 2026.09.01 — ${state.asOf?.replaceAll('-','.')||'2026.09.27'}</span></div>`+executiveKpis(financial)+`<div class="executive-grid"><section class="panel"><div class="panel-head"><h2>订单收入趋势</h2><span class="legend"><i></i> 累计订单金额</span></div><div class="chart-summary"><strong>${money(m.value)}</strong><small>本月累计 · ${m.orders.length} 笔</small></div>${chart()}<div class="chart-note">按订单日期汇总 · 人民币 / 不含税</div></section><div class="executive-right"><section class="panel"><div class="panel-head"><h2>${financial?'月结进度':'我的待办'} <span>${financial?state.journals.length:approvalQueue().length}</span></h2><button class="text-btn" data-route="${financial?'finance':'approvals'}">查看全部 ${icon('arrow')}</button></div><div class="approval-list">${financial?[['已入账订单',state.journals.length+' 笔','journals'],['结算差异',money(m.pending.reduce((s,o)=>s+o.variance,0)),'finance'],['账期状态',state.monthClosed?'已锁定':'开放中','finance']].map(x=>`<button class="approval-row" data-route="${x[2]}">${icon('receipt')}<span>${x[0]}</span>${badge(x[1],x[0]==='结算差异'?'warn':'good')}</button>`).join(''):approvalQueue().slice(0,3).map(a=>`<button class="approval-row" data-action="${a.action}" data-id="${a.id}">${icon(a.type==='质检'?'quality':'orders')}<span>${a.type}审批 · ${a.id}</span>${badge(a.status,'warn')}</button>`).join('')||'<div class="empty">所有审批已处理。</div>'}</div></section><section class="panel"><div class="panel-head"><h2>渠道收入贡献</h2><button class="text-btn" data-route="channels">渠道分析 ${icon('arrow')}</button></div>${channelSummary()}</section></div></div>`+pipeline()+`<section class="panel table-panel tabs-spacer"><div class="panel-head"><h2>${financial?'待结算订单':'重点订单'}</h2><button class="text-btn" data-route="${financial?'finance':'orders'}">全部订单 ${icon('arrow')}</button></div>${compactOrders((financial?m.pending:m.orders.filter(o=>o.status!=='已入账')).slice(0,5))}<div class="table-footer"><span>当前方案：${SCENARIOS.find(s=>s.id===activeScenario).name} · ${m.orders.length} 笔订单</span><span>订单 → 履约 → 结算 → 凭证</span></div></section>`+footer();}
function orderFlowDetail(o){if(!o)return '<div class="empty">选择订单以查看完整链路。</div>';const p=product(o.sku),po=state.purchaseOrders.filter(x=>x.sourceOrder===o.id),mo=state.workOrders.filter(x=>x.sourceOrder===o.id),j=state.journals.find(x=>x.order===o.id),step=['待审核','待发货','待结算','已入账'].indexOf(o.status);return `<section class="panel"><div class="flow-state-row"><span class="subtext">订单业务追踪</span>${statusBadge(o.status)}</div><div class="flow-selected-id mono">${o.id}</div><p class="subtext">${esc(o.customer)}<br>${p.name} · ${o.qty} 台</p><div class="detail-grid tabs-spacer"><div><span>订单金额</span><strong>${money(amount(o))}</strong></div><div><span>可用库存</span><strong class="${p.stock<o.qty?'negative':''}">${p.stock} 台</strong></div></div><div class="flow-timeline">${[['订单建立','客户、渠道、SKU 与单价已归档'],['审核与交付',step>=2?'已出库，库存台账已更新':step===1?'审核通过，等待仓库出库':'等待审核，校验客户与可用库存'],['结算与核对',step>=3?'结算已核对，费用差异已归因':step===2?'待核对平台费用与实际到账':'待订单交付后进入结算'],['凭证与审计',j?j.id+' · 借贷平衡':'完成结算后自动生成凭证']].map((x,i)=>`<div class="timeline-item ${i<=step?'completed':'pending'}"><strong>${x[0]}</strong><p>${x[1]}</p></div>`).join('')}</div><div class="actions">${o.status==='待审核'||o.status==='待发货'?btn(o.status==='待审核'?'审核订单':'确认出库','order-next','primary small',`data-id="${o.id}"`):o.status==='待结算'?btn('核对并入账','reconcile','primary small',`data-id="${o.id}"`):btn('查看会计凭证','journal-detail','primary small',`data-id="${o.id}"`)}${btn('来源详情','order-detail','small',`data-id="${o.id}"`)}</div><h3 class="section-title">关联单据</h3><div class="doc-links">${po.map(x=>`<button class="doc-link" data-action="po-detail" data-id="${x.id}">${x.id} · ${x.status}</button>`).join('')}${mo.map(x=>`<button class="doc-link" data-action="linked-mo" data-id="${x.id}">${x.id} · ${x.status}</button>`).join('')}${j?`<button class="doc-link" data-action="journal-detail" data-id="${o.id}">${j.id}</button>`:''}${!po.length&&!mo.length&&!j?'<span class="subtext">暂无关联单据，可按订单创建补货或工单。</span>':''}</div><div class="actions">${btn('按订单补货','order-procure','small',`data-id="${o.id}"`)}${btn('创建生产需求','order-produce','small',`data-id="${o.id}"`)}</div></section>`;}
function flowWorkbench(){const rows=state.orders.filter(o=>(filter==='all'||filter===o.biz)&&(statusFilter==='all'||o.status===statusFilter)&&(!orderQuery||(o.id+' '+o.customer+' '+o.sku).toLowerCase().includes(orderQuery.toLowerCase())));const pages=Math.max(1,Math.ceil(rows.length/6));flowPage=Math.min(flowPage,pages);const o=state.orders.find(x=>x.id===selectedOrder)||rows[0];return head('全链路业务工作台','BUSINESS OPERATIONS','以订单为主线，协同客户、采购、制造、仓储与财务。',btn(icon('download')+'导出台账','export')+btn(icon('plus')+'新建订单','new-order','primary'))+kpis([['进行中订单',state.orders.filter(x=>x.status!=='已入账').length,'笔','覆盖 TOC 与 TOB 业务','orders'],['采购在途',state.purchaseOrders.filter(x=>x.status==='待收货').reduce((s,x)=>s+x.qty,0),'台','已审批，等待收货','truck'],['生产任务',state.workOrders.filter(x=>x.status!=='已完工').length,'笔','排产 / 报工 / 质量验收','factory'],['库存预警',state.products.filter(p=>p.stock/p.daily<30).length,'项','低于 30 天目标覆盖','alert']])+pipeline()+`<div class="flow-layout tabs-spacer"><section class="panel table-panel"><div class="panel-head"><h2>订单协同台账</h2><span class="section-caption">选择订单，查看业务全程</span></div><div class="toolbar"><input class="input" id="order-search" placeholder="搜索订单、客户或 SKU" aria-label="搜索订单" value="${esc(orderQuery)}"><select class="select" id="order-status" aria-label="订单状态">${['all','待审核','待发货','待结算','已入账'].map(x=>`<option value="${x}" ${x===statusFilter?'selected':''}>${x==='all'?'全部状态':x}</option>`).join('')}</select></div>${compactOrders(rows.slice((flowPage-1)*6,flowPage*6),'flow')}<div class="table-footer"><span>共 ${rows.length} 笔 · 每页 6 笔</span><div class="pagination">${Array.from({length:pages},(_,i)=>`<button data-flow-page="${i+1}" class="${flowPage===i+1?'active':''}" aria-label="第 ${i+1} 页">${i+1}</button>`).join('')}</div></div></section><div class="flow-right">${orderFlowDetail(o)}<section class="panel"><div class="panel-head"><h2>交付关注</h2>${icon('alert')}</div>${state.products.filter(p=>p.stock/p.daily<30).slice(0,3).map(p=>`<div class="list-row"><div><strong>${p.sku}</strong><div class="subtext">覆盖 ${(p.stock/p.daily).toFixed(1)} 天 · 目标 30 天</div></div>${btn('补货','new-po','small secondary',`data-sku="${p.sku}"`)}</div>`).join('')||'<p class="subtext">库存覆盖处于目标范围。</p>'}</section></div></div>`+footer();}
function approvalsPage(){const queue=approvalQueue(),rows=queue.filter(a=>approvalType==='all'||a.type===approvalType);return head('审批中心','APPROVAL CENTER','将经营事项集中处理，让审批结果直接推动业务流转。')+kpis([['待处理事项',queue.length,'项','订单审核 / 采购审批 / 质量验收','check'],['订单待审',queue.filter(a=>a.type==='订单').length,'笔','审批通过后进入履约','orders'],['采购待审',queue.filter(a=>a.type==='采购').length,'笔','审批后计入采购在途','briefcase'],['质量待验',queue.filter(a=>a.type==='质检').length,'笔','合格后计入成品库存','quality']])+`<div class="tabline">${[['all','全部事项'],['订单','订单审核'],['采购','采购审批'],['质检','质量验收']].map(x=>`<button data-approval-type="${x[0]}" class="${approvalType===x[0]?'active':''}">${x[1]}</button>`).join('')}</div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>业务单据</th><th>事项类型</th><th>产品 / 数量</th><th>金额 / 标准成本</th><th>责任域</th><th>处理</th></tr></thead><tbody>${rows.map(a=>`<tr><td class="mono">${a.id}</td><td>${badge(a.type,'purple')}</td><td>${a.title}</td><td>${money(a.amount)}</td><td>${a.owner}</td><td>${btn('审核处理',a.action,'small secondary',`data-id="${a.id}"`)}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty">当前类别的事项已全部处理。</div>'}</div></section>`+footer();}
function subpage(fn,tab,key,title,subtitle){return()=>{if(tab==='finance')financeTab=key;if(tab==='data')dataTab=key;if(tab==='compliance')complianceTab=key;if(tab==='strategy')strategyTab=key;let html=fn();const template=document.createElement('template');template.innerHTML=html;template.content.querySelectorAll('.tabline').forEach(e=>e.remove());const h=template.content.querySelector('h1');if(h)h.textContent=title;const p=template.content.querySelector('.pagehead p');if(p&&subtitle)p.textContent=subtitle;return template.innerHTML;};}
function settingsPage(){return head('工作空间设置','WORKSPACE PREFERENCES','选择适合当前工作方式的界面与业务方案。')+`<div class="panel-head"><h2>界面风格</h2><small>三套独立视觉 · 所有业务功能一致</small></div><div class="settings-grid">${THEMES.map(t=>`<button class="theme-choice ${uiTheme===t.id?'selected':''}" data-theme-choice="${t.id}"><img src="${t.image}" alt="${t.name}界面预览"><span class="theme-info"><span>${t.name}<br><small>${t.description}</small></span>${uiTheme===t.id?icon('check'):icon('arrow')}</span></button>`).join('')}</div><div class="panel-head tabs-spacer"><h2>业务方案</h2><small>业务数据与操作记录分别保存</small></div><div class="settings-grid">${SCENARIOS.map(s=>`<button class="scenario-choice ${activeScenario===s.id?'selected':''}" data-scenario-choice="${s.id}"><h3>${s.name}</h3><p>${s.subtitle}<br>${s.description}</p><small>${activeScenario===s.id?'当前方案 · ':''}24 笔初始订单 · 采购、工单、凭证齐备</small></button>`).join('')}</div><section class="panel tabs-spacer"><div class="panel-head"><h2>显示与数据管理</h2></div><div class="list-row"><div><strong>信息密度</strong><div class="subtext">调整表格与菜单间距</div></div><select id="density-select" class="select" aria-label="信息密度"><option value="comfortable" ${uiDensity==='comfortable'?'selected':''}>舒适</option><option value="compact" ${uiDensity==='compact'?'selected':''}>紧凑</option></select></div><div class="list-row"><div><strong>恢复当前方案</strong><div class="subtext">仅恢复「${SCENARIOS.find(s=>s.id===activeScenario).name}」的初始业务数据</div></div>${btn('恢复初始数据','reset')}</div><div class="list-row"><div><strong>关于鼎匠 ONE</strong><div class="subtext">版本、数据口径与研究依据</div></div>${btn('查看说明','about')}</div></section>`+footer();}
function render(){if(!views[route])route='overview';chartInstances.forEach(c=>c.dispose());chartInstances=[];document.body.dataset.theme=uiTheme;document.body.dataset.density=uiDensity;const navScroll=document.querySelector('.sidebar-nav')?.scrollTop||0;shell();document.querySelector('#content').innerHTML=views[route]();if(!document.querySelector('.pagefoot'))document.querySelector('#content').insertAdjacentHTML('beforeend',footer());document.title=(nav.find(n=>n[0]===route)?.[1]||'集团工作空间')+' · 鼎匠 ONE';document.querySelector('.sidebar-nav').scrollTop=navScroll;const active=document.querySelector('.navitem.active');if(active){const rect=active.getBoundingClientRect(),n=document.querySelector('.sidebar-nav').getBoundingClientRect();if(rect.bottom>n.bottom||rect.top<n.top)active.scrollIntoView({block:'nearest'});}requestAnimationFrame(drawCharts);}
function drawCharts(){const el=document.querySelector('#revenue-chart');if(!el||!window.echarts)return;const color=getComputedStyle(document.body).getPropertyValue('--accent').trim(),muted=getComputedStyle(document.body).getPropertyValue('--muted').trim(),line=getComputedStyle(document.body).getPropertyValue('--line').trim();let sum=0;const days=Array.from({length:27},(_,i)=>i+1),values=days.map(d=>{sum+=businessMetrics().orders.filter(o=>+o.date.slice(-2)===d).reduce((s,o)=>s+amount(o),0);return +sum.toFixed(2)});const c=echarts.init(el);c.setOption({animationDuration:450,grid:{left:4,right:12,top:20,bottom:7,containLabel:true},tooltip:{trigger:'axis',valueFormatter:v=>money(v)},xAxis:{type:'category',boundaryGap:false,data:days.map(d=>'09/'+String(d).padStart(2,'0')),axisLine:{show:false},axisTick:{show:false},axisLabel:{color:muted,fontSize:10,interval:5}},yAxis:{type:'value',splitNumber:4,axisLabel:{color:muted,fontSize:10,formatter:v=>v>=10000?(v/10000).toFixed(0)+'万':v},splitLine:{lineStyle:{color:line,type:'dashed'}}},series:[{name:'累计订单金额',type:'line',smooth:.25,showSymbol:false,data:values,lineStyle:{color,width:2.5},itemStyle:{color},areaStyle:{color:new echarts.graphic.LinearGradient(0,0,0,1,[{offset:0,color:uiTheme==='midnight'?'#6eb9ff38':'#5065e929'},{offset:1,color:'#5065e900'}])}}]});chartInstances.push(c);}
window.addEventListener('resize',()=>chartInstances.forEach(c=>c.resize()));
Object.assign(views,{overview:executiveOverview,flow:flowWorkbench,approvals:approvalsPage,customers:customersPage,channels:channelsPage,procurement:procurementPage,inventory:subpage(supplyView,null,null,'库存计划'),production:subpage(productionView,null,null,'生产工单'),warehouses:warehousePage,products:productsPage,quality:qualityPage,receivables:receivablesPage,suppliers:suppliersPage,integrations:integrationsPage,finance:subpage(financeView,'finance','settlements','结算对账'),journals:subpage(financeView,'finance','journals','会计凭证'),profit:subpage(financeView,'finance','profit','产品损益'),data:subpage(dataView,'data','quality','数据质量'),lineage:subpage(dataView,'data','lineage','指标血缘'),dictionary:subpage(dataView,'data','dictionary','指标字典'),controls:subpage(complianceView,'compliance','controls','内控与证据'),audit:subpage(complianceView,'compliance','audit','操作审计'),access:subpage(complianceView,'compliance','access','角色与权限'),projects:subpage(strategyView,'strategy','roadmap','项目与预算'),assets:subpage(strategyView,'strategy','assets','IT 资产'),strategy:subpage(strategyView,'strategy','blueprint','建设蓝图'),research:subpage(strategyView,'strategy','research','调研与建设依据'),settings:settingsPage});
function changeScenario(id){if(!SCENARIOS.some(s=>s.id===id))return;document.querySelector('#dialog').close();dialogConfirm=null;setActiveScenario(id);resetCheckpoint();dashboardFilter='all';render();toast('已切换至「'+SCENARIOS.find(s=>s.id===id).name+'」，操作记录独立保存。');}
function changeTheme(id){if(!THEMES.some(t=>t.id===id))return;uiTheme=id;savePreferences();render();}
function linkedDemand(id,type){if(!guard('supply'))return;const o=state.orders.find(o=>o.id===id);if(!o)return;const p=product(o.sku),list=type==='PO'?state.purchaseOrders:state.workOrders,label=type==='PO'?'采购补货':'生产需求';formModal(o.id+' · '+label,`<div class="notice">来源订单 ${o.id} · ${esc(o.customer)}<br>${p.name} · 需求 ${o.qty} 台 / 可用 ${p.stock} 台</div><div class="form-grid tabs-spacer">${field('产品 SKU',`<input class="input" value="${p.sku}" readonly>`)}${field('需求数量',`<input class="input" type="number" name="qty" min="1" max="100000" value="${Math.max(o.qty-p.stock,o.qty)}" required>`)}${field('需求说明',`<input class="input" name="reason" value="保障 ${o.id} 交付" maxlength="120" required>`,true)}</div>`,type==='PO'?'提交采购申请':'创建生产工单',v=>{if(!guard('supply'))return;const qty=requireInteger(v.qty,1,100000,'需求数量'),newId=type+'-2609-'+String(list.length+1).padStart(3,'0');list.unshift({id:newId,sku:p.sku,qty,status:type==='PO'?'待审核':'待排产',sourceOrder:o.id,date:state.asOf,reason:v.reason.trim(),line:'装配中心',bom:p.bom.split('-').pop()});log('创建关联'+label,newId,`来源 ${o.id}；${p.sku} × ${qty}；${v.reason.trim()}`);finish(label+'已创建并关联来源订单。');});}
const originalExport=exportData;
function downloadRows(name,rows){const csv='\ufeff'+rows.map(r=>r.map(x=>'"'+String(x??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='鼎匠ONE-'+name+'-'+activeScenario+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);toast('已导出 '+name);}
function enterpriseExport(){if(['overview','flow'].includes(route))return downloadRows('订单协同台账',[['订单','客户','渠道','SKU','数量','金额','状态'],...state.orders.map(o=>[o.id,o.customer,o.channel,o.sku,o.qty,amount(o),o.status])]);if(['inventory','warehouses','products'].includes(route))return downloadRows('库存台账',[['SKU','产品','仓库','库存','标准成本'],...state.products.map(p=>[p.sku,p.name,p.warehouse,p.stock,p.cost])]);if(route==='procurement')return downloadRows('采购台账',[['采购单','来源订单','SKU','数量','状态'],...state.purchaseOrders.map(p=>[p.id,p.sourceOrder,p.sku,p.qty,p.status])]);if(['journals','profit','receivables'].includes(route))return downloadRows('财务台账',[['订单','收入','费用','成本','贡献利润','状态'],...state.orders.map(o=>[o.id,amount(o),fee(o)+freight(o)+o.variance,cost(o),profit(o),o.status])]);if(['audit','controls','access'].includes(route))return downloadRows('审计记录',[['时间','角色','动作','单据','详情'],...state.audit.map(a=>[a.time,a.actor,a.action,a.object,a.detail])]);return originalExport();}
Object.assign(actions,{'export':()=>enterpriseExport(),'open-workbench':()=>goto('flow'),'select-order':el=>{selectedOrder=el.dataset.id;if(route==='flow'||route==='overview'&&uiTheme==='graphite')render();else goto('flow')},'open-flow':el=>{selectedOrder=el.dataset.id;goto('flow')},'order-procure':el=>linkedDemand(el.dataset.id,'PO'),'order-produce':el=>linkedDemand(el.dataset.id,'MO'),'linked-mo':el=>{const w=state.workOrders.find(w=>w.id===el.dataset.id);if(w)modal(w.id+' · 生产工单',`<div class="detail-grid">${[['产品',w.sku],['数量',w.qty+' 台'],['BOM',w.bom],['状态',w.status],['来源订单',w.sourceOrder||'独立生产需求'],['产线',w.line]].map(x=>`<div><span>${x[0]}</span><strong>${esc(x[1])}</strong></div>`).join('')}</div>`,btn('关闭','close')+(w.status==='已完工'?'':btn('推进工单','mo-next','primary',`data-id="${w.id}"`)))},'to-finance':el=>goto('finance'),'to-audit':()=>goto('audit'),'about':()=>modal('关于鼎匠 ONE',`<div class="brand" style="padding:0;margin-bottom:20px"><img src="assets/logo.png" alt="鼎匠 ONE"><div><h2>鼎匠 ONE</h2><small>BUSINESS OPERATING SYSTEM · 2.0</small></div></div><p>面向跨境产供销与业财协同的交互式产品原型。业务数据为合成业务样本，操作保存在当前浏览器，不连接企业生产系统。</p><p>金额使用人民币、不含税与固定标准成本。权限为本地交互范围控制；备份、集成和合规页面用于管理流程验证。</p><p>品牌与产品研究依据公开资料；本产品并非 TOPDON 官方系统。</p>`,btn('研究与建设依据','open-research','primary')+btn('关闭','close')),'open-research':()=>goto('research'),'notifications':()=>modal('待办通知',`<div class="notifications-panel">${approvalQueue().slice(0,6).map(a=>`<div class="list-row"><div><strong>${a.type} · ${a.id}</strong><div class="subtext">${a.title}</div></div>${btn('处理',a.action,'small secondary',`data-id="${a.id}"`)}</div>`).join('')||'<p class="empty">暂无待办事项。</p>'}</div>`,btn('进入审批中心','open-approvals','primary')),'open-approvals':()=>goto('approvals'),'reset':()=>confirm('恢复「'+SCENARIOS.find(s=>s.id===activeScenario).name+'」初始数据','<p>当前业务方案的新增单据和操作记录将被恢复。其他业务方案保持不变。</p>','恢复当前方案',()=>{state=buildScenario(activeScenario);persist();resetCheckpoint();finish('当前业务方案已恢复。')})});
document.addEventListener('change',e=>{if(e.target.id==='scenario-select')changeScenario(e.target.value);if(e.target.id==='theme-select')changeTheme(e.target.value);if(e.target.id==='density-select'){uiDensity=e.target.value;savePreferences();render();}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-group],[data-theme-choice],[data-scenario-choice],[data-flow-page],[data-approval-type],[data-dashboard-filter]');if(!el)return;if(el.dataset.group){const id=el.dataset.group;collapsedGroups.has(id)?collapsedGroups.delete(id):collapsedGroups.add(id);el.setAttribute('aria-expanded',!collapsedGroups.has(id));el.closest('.nav-group').classList.toggle('collapsed',collapsedGroups.has(id));}if(el.dataset.themeChoice)changeTheme(el.dataset.themeChoice);if(el.dataset.scenarioChoice)changeScenario(el.dataset.scenarioChoice);if(el.dataset.flowPage){flowPage=+el.dataset.flowPage;render();}if(el.dataset.approvalType){approvalType=el.dataset.approvalType;render();}if(el.dataset.dashboardFilter){dashboardFilter=el.dataset.dashboardFilter;render();}});
const baseModal=modal;
modal=function(title,body,foot='',callback=null){const openingBook=state;baseModal(title,body,foot,callback?()=>{if(state!==openingBook){toast('业务方案已切换，请重新打开单据。');return;}callback();}:null);};
const baseFormModal=formModal;
formModal=function(title,body,submit,handler){const openingBook=state;baseFormModal(title,body,submit,v=>{if(state!==openingBook)throw Error('业务方案已切换，请重新打开单据。');handler(v);});};
const baseReset=actions.reset;
actions.reset=()=>{if(!guard('admin'))return;baseReset();const resetCallback=dialogConfirm;dialogConfirm=()=>{if(guard('admin'))resetCallback?.();};};
render();
